<script setup lang="ts">import {ref,computed,watch} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import RunList from '../components/RunList.vue';import {catalogApi} from '../api/catalog';import {researchApi} from '../api/research';import {useTask} from '../hooks/useTask';const p=defineProps<{studies:any[];traces:any[];profiles:any[];runs:any[];user:any;reloadCatalog:()=>Promise<void>;reloadResearch:()=>Promise<void>}>(),emit=defineEmits(['open']);const id=ref(0),pid=ref(0),name=ref('固定模型 '+new Date().toLocaleTimeString()),version=ref('v1'),raw=ref(''),runName=ref('固定HMM推断 '+new Date().toLocaleTimeString()),selected=ref<number[]|null>(null),task=useTask(),study=computed(()=>p.studies.find(s=>s.id===(id.value||p.studies[0]?.id))),rows=computed(()=>p.traces.filter(t=>t.study_id===study.value?.id)),available=computed(()=>p.profiles.filter(m=>m.study_id===study.value?.id)),profile=computed(()=>available.value.find(m=>m.id===pid.value)||available.value[0]),ids=computed(()=>selected.value===null?rows.value.slice(0,20).map(t=>t.id):selected.value);watch(()=>study.value?.id,()=>{pid.value=0;selected.value=null;const M=study.value?.symbols.length||3;raw.value=JSON.stringify({states:['假设甲','假设乙'],pi:[.6,.4],transition:[[.7,.3],[.4,.6]],emission:M===3?[[.5,.4,.1],[.1,.3,.6]]:[Array(M).fill(1/M),Array(M).fill(1/M)]},null,2)},{immediate:true});function toggle(t:number){selected.value=ids.value.includes(t)?ids.value.filter(v=>v!==t):[...ids.value,t]}async function freeze(){await task.act(async()=>{const model=await catalogApi.createProfile({study_id:study.value.id,name:name.value,version:version.value,...JSON.parse(raw.value)});await p.reloadCatalog();pid.value=model.id},'模型参数版本已冻结，不做EM')}async function infer(){await task.act(async()=>{const r=await researchApi.createRun({study_id:study.value.id,profile_id:profile.value.id,name:runName.value,trace_ids:ids.value});await p.reloadResearch();emit('open',r)},'固定模型与轨迹快照已排队')}</script><template><PageTitle index="03" title="参数是预设假设，推断不是训练。" description="π/A/B有限非负；行和仅在1±1e-8内记录归一，真实0不加epsilon。"/><label>推断研究<select :value="study?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><div class="config-layout"><form class="input-panel" @submit.prevent="freeze"><small>01 / FREEZE PARAMETERS</small><h2>建立固定参数版本</h2><label>模型名称<input v-model="name" required/></label><label>版本<input v-model="version" required/></label><label>模型参数 JSON<textarea v-model="raw" rows="16"/></label><p>状态2–5，发射列对应 {{study?.symbols.join(' / ')}}。所有维度和概率行和在后端验证。</p><button v-if="user.role!=='viewer'" class="primary" :disabled="task.state.busy||!study">冻结模型版本 →</button></form><form class="selection-panel" @submit.prevent="infer"><small>02 / INFER SELECTED TRACES</small><h2>选择模型与观测轨迹</h2><label>固定模型版本<select :value="profile?.id||0" @change="pid=Number(($event.target as HTMLSelectElement).value)"><option v-for="m in available" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>运行名称<input v-model="runName" required/></label><p>已选{{ids.length}}/30条；默认前20条。模型{{profile?.version||'尚未建立'}}，不更新参数。</p><div class="selection-actions"><button type="button" @click="selected=rows.slice(0,20).map(t=>t.id)">默认前20条</button><button type="button" @click="selected=[]">清空选择</button></div><div class="trace-picker"><label v-for="t in rows" :key="t.id"><input type="checkbox" :checked="ids.includes(t.id)" @change="toggle(t.id)" :aria-label="'选择-'+t.reference"/><span>{{t.reference}}<small>{{t.tokens.length}}码 / {{t.tokens.slice(0,8).join(' ')}}</small></span></label></div><button v-if="user.role!=='viewer'" class="primary" :disabled="task.state.busy||!profile||ids.length<1||ids.length>30">送入log域推断队列 →</button></form></div><Notice v-bind="task.state"/><section class="section"><h2>队列与归档</h2><RunList :runs="runs" @open="emit('open',$event)"/></section></template>
